(function() {
  'use strict';

  require(['jquery', 'xwiki-meta'], function($, xwikiMeta) {
    const TASK_LIST_CLASS = 'task-list';
    const TASK_ITEM_CLASS = 'task-list-item';
    const TASK_ITEM_CHECKED_CLASS = 'task-list-item-checked';
    const TOGGLE_CLASS = 'xwiki-task-list-toggle';
    const TASK_INDEX_ATTRIBUTE = 'data-xwiki-task-index';
    const UNCHECKED_MARKER = '[ ] ';
    const CHECKED_MARKER = '[x] ';
    const serviceURL = '$escapetool.javascript($xwiki.getURL("CKEditor.TaskListService", "get"))';
    const styleId = 'xwiki-task-list-style';

    const injectStyle = function() {
      if (document.getElementById(styleId)) {
        return;
      }
      const style = document.createElement('style');
      style.id = styleId;
      style.textContent = [
        'ul.' + TASK_LIST_CLASS + ' { list-style: none; padding-left: 40px; }',
        'li.' + TASK_ITEM_CLASS + ' { list-style: none; }',
        'ul.' + TASK_LIST_CLASS + ' > li.' + TASK_ITEM_CLASS + ' { position: relative; padding-left: 0; }',
        'ul.' + TASK_LIST_CLASS + ' > li.' + TASK_ITEM_CLASS + ' > .' + TOGGLE_CLASS + ' {',
        '  position: absolute;',
        '  left: -1.75rem;',
        '  top: 0.1rem;',
        '  width: 1.25rem;',
        '  height: 1.25rem;',
        '  border: 1px solid currentColor;',
        '  border-radius: 0.2rem;',
        '  background: transparent;',
        '  cursor: pointer;',
        '  padding: 0;',
        '}',
        'ul.' + TASK_LIST_CLASS + ' > li.' + TASK_ITEM_CLASS + ' > .' + TOGGLE_CLASS + '::after {',
        '  content: "";',
        '  position: absolute;',
        '  left: 0.32rem;',
        '  top: 0.32rem;',
        '  width: 0.55rem;',
        '  height: 0.3rem;',
        '  border-left: 2px solid currentColor;',
        '  border-bottom: 2px solid currentColor;',
        '  transform: rotate(-45deg) scale(0);',
        '  transform-origin: center;',
        '}',
        'ul.' + TASK_LIST_CLASS + ' > li.' + TASK_ITEM_CLASS + '.' +
          TASK_ITEM_CHECKED_CLASS + ' > .' + TOGGLE_CLASS + '::after {',
        '  transform: rotate(-45deg) scale(1);',
        '}',
        'ul.' + TASK_LIST_CLASS + ' > li.' + TASK_ITEM_CHECKED_CLASS + ' { color: #7a7a7a; }',
        'ul.' + TASK_LIST_CLASS + ' > li.' + TASK_ITEM_CLASS +
          '[data-task-saving="true"] > .' + TOGGLE_CLASS + ' {',
        '  opacity: 0.55;',
        '  cursor: wait;',
        '}'
      ].join('');
      document.head.appendChild(style);
    };

    const MARKER_PATTERN = /^(\s*)\[( |x)\]\s/;

    const getFirstTextNode = function(node, includeChildren) {
      let child = node.firstChild;
      while (child) {
        if (child.nodeType === Node.TEXT_NODE && child.nodeValue.trim() !== '') {
          return child;
        }
        if (includeChildren && child.nodeType === Node.ELEMENT_NODE &&
            child.tagName !== 'UL' && child.tagName !== 'OL') {
          const descendant = getFirstTextNode(child, true);
          if (descendant) {
            return descendant;
          }
        }
        child = child.nextSibling;
      }
      return null;
    };

    const getTaskMarker = function(listItem) {
      const textNode = getFirstTextNode(listItem, true);
      const text = textNode ? textNode.nodeValue : '';
      const match = text.match(MARKER_PATTERN);
      if (!match) {
        return null;
      }
      return {
        checked: match[2] === 'x',
        markerLength: match[0].length,
        textNode: textNode
      };
    };

    const getTaskState = function(listItem) {
      const marker = getTaskMarker(listItem);
      if (marker) {
        return marker.checked;
      }
      if (listItem.classList.contains(TASK_ITEM_CLASS)) {
        return listItem.classList.contains(TASK_ITEM_CHECKED_CLASS);
      }
      return null;
    };

    const removeVisibleMarker = function(listItem) {
      const marker = getTaskMarker(listItem);
      if (!marker) {
        return;
      }
      marker.textNode.nodeValue = marker.textNode.nodeValue.substring(marker.markerLength);
    };

    const setTaskState = function(listItem, checked) {
      let textNode = getFirstTextNode(listItem, true);
      let markerData;
      if (!textNode) {
        textNode = document.createTextNode('');
        listItem.insertBefore(textNode, listItem.firstChild);
      }
      const marker = checked ? CHECKED_MARKER : UNCHECKED_MARKER;
      const text = textNode.nodeValue || '';
      markerData = getTaskMarker(listItem);
      if (markerData) {
        textNode.nodeValue = marker + text.substring(markerData.markerLength);
      } else {
        textNode.nodeValue = marker + text;
      }
    };

    const getButton = function(listItem) {
      const firstElementChild = listItem.firstElementChild;
      if (firstElementChild && firstElementChild.classList.contains(TOGGLE_CLASS)) {
        return firstElementChild;
      }
      return null;
    };

    const updateButton = function(listItem) {
      const button = getButton(listItem);
      if (!button) {
        return;
      }
      const checked = listItem.classList.contains(TASK_ITEM_CHECKED_CLASS);
      button.setAttribute('aria-pressed', checked ? 'true' : 'false');
      button.setAttribute('title', checked ? 'Mark as not done' : 'Mark as done');
    };

    const enhanceTaskItem = function(listItem, index) {
      const checked = getTaskState(listItem);
      if (checked === null) {
        listItem.classList.remove(TASK_ITEM_CLASS, TASK_ITEM_CHECKED_CLASS);
        listItem.removeAttribute(TASK_INDEX_ATTRIBUTE);
        return false;
      }

      listItem.classList.add(TASK_ITEM_CLASS);
      listItem.classList.toggle(TASK_ITEM_CHECKED_CLASS, checked);
      listItem.setAttribute(TASK_INDEX_ATTRIBUTE, String(index));
      removeVisibleMarker(listItem);

      let button = getButton(listItem);
      if (!button) {
        button = document.createElement('button');
        button.type = 'button';
        button.className = TOGGLE_CLASS;
        button.setAttribute('aria-label', 'Toggle task state');
        button.addEventListener('click', onToggle);
        listItem.insertBefore(button, listItem.firstChild);
      }
      updateButton(listItem);
      return true;
    };

    const enhance = function(root) {
      let taskIndex = 0;
      root.querySelectorAll('ul, ol').forEach(function(list) {
        const directListItems = Array.from(list.children).filter(function(child) {
          return child.tagName === 'LI';
        });
        const taskStates = directListItems.map(getTaskState);
        const isTaskList = directListItems.length > 0 && (
          list.classList.contains(TASK_LIST_CLASS) ||
          directListItems.some(function(listItem, index) {
            return taskStates[index] !== null || listItem.classList.contains(TASK_ITEM_CLASS);
          })
        );

        list.classList.toggle(TASK_LIST_CLASS, isTaskList);
        if (!isTaskList) {
          directListItems.forEach(function(listItem) {
            listItem.classList.remove(TASK_ITEM_CLASS, TASK_ITEM_CHECKED_CLASS);
            listItem.removeAttribute(TASK_INDEX_ATTRIBUTE);
          });
          return;
        }

        directListItems.forEach(function(listItem) {
          if (enhanceTaskItem(listItem, taskIndex)) {
            taskIndex += 1;
          }
        });
      });
    };

    const getAnnotatedHTML = function(documentReference) {
      return $.get(serviceURL, {
        taskAction: 'get',
        documentReference: documentReference
      });
    };

    const saveAnnotatedHTML = function(documentReference, html) {
      const csrfToken = xwikiMeta.form_token || $('meta[name="form_token"]').attr('content') ||
        (window.xcontext && window.xcontext.form_token) || '';
      return $.post(serviceURL, {
        taskAction: 'save',
        documentReference: documentReference,
        form_token: csrfToken,
        html: html
      });
    };

    const getTaskItems = function(container) {
      const result = [];
      container.querySelectorAll('ul, ol').forEach(function(list) {
        Array.from(list.children).forEach(function(child) {
          if (child.tagName === 'LI' && getTaskState(child) !== null) {
            result.push(child);
          }
        });
      });
      return result;
    };

    async function onToggle(event) {
      event.preventDefault();
      const listItem = event.currentTarget.parentElement;
      if (!listItem || listItem.dataset.taskSaving === 'true') {
        return;
      }

      const documentReference = XWiki.Model.serialize(XWiki.currentDocument.documentReference);
      const taskIndex = Number(listItem.getAttribute(TASK_INDEX_ATTRIBUTE));
      const nextChecked = !listItem.classList.contains(TASK_ITEM_CHECKED_CLASS);

      listItem.dataset.taskSaving = 'true';
      listItem.classList.toggle(TASK_ITEM_CHECKED_CLASS, nextChecked);
      updateButton(listItem);

      try {
        const annotatedHTML = await getAnnotatedHTML(documentReference);
        const container = document.createElement('div');
        container.innerHTML = annotatedHTML;
        const taskItems = getTaskItems(container);
        if (!taskItems[taskIndex]) {
          throw new Error('Missing task item at index [' + taskIndex + '].');
        }
        setTaskState(taskItems[taskIndex], nextChecked);
        await saveAnnotatedHTML(documentReference, container.innerHTML);
      } catch (error) {
        listItem.classList.toggle(TASK_ITEM_CHECKED_CLASS, !nextChecked);
        updateButton(listItem);
        console.error('Failed to persist the task list state.', error);
      } finally {
        delete listItem.dataset.taskSaving;
      }
    }

    $(function() {
      injectStyle();
      enhance(document);
      $(document).on('xwiki:dom:updated', function() {
        enhance(document);
      });
    });
  });
})();
